  const foot=[asOf?`数据截至 ${String(asOf).slice(0,30)}`:'',source?String(source).slice(0,90):''].filter(Boolean).map(esc).join(' · ');
  const manager=fundValue(data,'manager','fundManager'),note=fundValue(data,'note','description');
  return `<article class="agent-fund-card${compact?' compact':''}"><header><div>${/^\d{6}$/.test(code)?`<button type="button" class="agent-fund-name-link" data-open-fund="${esc(code)}" aria-label="查看${esc(name)}基金详情">${esc(name.slice(0,100))} ↗</button><small>${esc(code)}</small>`:`<strong>${esc(name.slice(0,100))}</strong>`}</div><span class="agent-fund-mark">基金</span></header>${chips?`<div class="agent-fund-chips">${chips}</div>`:''}${specs.length?`<div class="agent-fund-metrics">${specs.map(([label,value,format])=>fundMetric(label,value,format)).join('')}</div>`:''}${manager?`<div class="agent-fund-detail">基金经理：${esc(String(manager).slice(0,80))}</div>`:''}${note?`<p class="agent-fund-note">${esc(String(note).slice(0,300))}</p>`:''}${foot?`<footer>${foot}</footer>`:''}</article>`;
