async function addHoldingsImages(fileList){const draft=state.holdingsImport;if(!draft)return;const files=Array.from(fileList||[]).filter(file=>file.type.startsWith('image/'));if(!files.length)return toast('请选择图片文件。');if(draft.images.length+files.length>12)return toast('一次最多上传 12 张截图。');try{for(const file of files){const bitmap=await createImageBitmap(file),scale=Math.min(1,2200/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.82));if(!blob)throw new Error('图片压缩失败。');if(blob.size>7_000_000)throw new Error('有图片压缩后仍超过 7 MB，请裁剪后重试。');const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('无法读取图片。'));reader.readAsDataURL(blob)});draft.images.push({name:file.name,dataUrl,size:blob.size})}render()}catch(error){toast(error.message||'读取截图失败，请换一张图片重试。')}}
