function onAgentEvent({method,params}){
  if(method==='thread/recovered'&&params?.session){const old=D.current?.threadId;if(old&&old!==params.session.threadId){forgetOpenSession(old);D.threadViews.delete(old)}D.current=params.session;rememberOpenSession(params.session.threadId);renderSessions();renderOpenTabs();renderAgentPanel();return}
  const threadId=params?.threadId,background=Boolean(threadId&&threadId!==D.current?.threadId),visible=background?snapshotThreadView():null;
  if(background)restoreThreadView(D.threadViews.get(threadId));
  if(method==='turn/started'){D.running=true;D.activeThreadId=threadId||D.current?.threadId;D.turnStartedAt=D.turnStartedAt||Date.now()}
  else if(method==='turn/completed'){D.running=false;D.pendingInput=null;D.turnStartedAt=null;if(D.activeThreadId===threadId)D.activeThreadId=null;window.fundDesktop.listSessions().then(desktopCall).then(x=>{D.sessions=x;D.current=x.find(s=>s.threadId===D.current?.threadId)||D.current;renderSessions();renderOpenTabs();renderAgentPanel()}).catch(()=>{})}
  else if(method==='item/tool/requestUserInput')D.pendingInput=params;
  else if(method==='item/tool/requestUserInput/resolved')D.pendingInput=null;
  else if(method==='item/agentMessage/delta'){let row=D.messages.find(x=>x.id===params.itemId);if(!row){row={id:params.itemId,role:'assistant',text:''};D.messages.push(row)}row.text+=params.delta||''}
  else if(method==='item/reasoning/summaryTextDelta'){let row=D.messages.find(x=>x.id===params.itemId);if(!row){row={id:params.itemId,type:'reasoning',text:'',streaming:true};D.messages.push(row)}row.text+=params.delta||''}
  else if(method==='item/completed'&&params.item?.type==='reasoning'){const text=reasoningText(params.item);let row=D.messages.find(x=>x.id===params.item.id);if(!row&&text)D.messages.push({id:params.item.id,type:'reasoning',text});else if(row){row.text=text||row.text;row.streaming=false}}
  else if(method==='turn/plan/updated'){let row=D.messages.find(x=>x.type==='plan'&&x.turnId===params.turnId);if(!row){row={id:'plan-'+Date.now(),turnId:params.turnId,type:'plan',text:planText(params.plan)};D.messages.push(row)}else row.text=planText(params.plan)}
  else if(method==='item/started'&&params.item?.type==='mcpToolCall'){const row={id:params.item.id,type:'tool',tool:params.item.tool,status:params.item.status};D.messages.push(row);D.tools.set(row.id,row)}
  else if(method==='item/completed'&&params.item?.type==='mcpToolCall'){const row=D.tools.get(params.item.id);if(row)Object.assign(row,{status:params.item.status,error:params.item.error})}
  else if(method==='item/completed'&&params.item?.type==='agentMessage'){let row=D.messages.find(x=>x.id===params.item.id);if(!row)D.messages.push({id:params.item.id,role:'assistant',text:params.item.text||''});else row.text=params.item.text||row.text;if(!background&&(state.nav==='market'||state.nav==='pages')){const changed=marketAcceptAIDraft(params.item.text||'')||marketAcceptAIMetricDraft(params.item.text||'');if(changed)render()}}
  else if(method==='error'){D.running=false;D.turnStartedAt=null;if(D.activeThreadId===threadId)D.activeThreadId=null;D.messages.push({role:'assistant',text:params.error?.message||params.message||'Agent 运行失败。',error:true})}
  if(threadId)D.threadViews.set(threadId,snapshotThreadView());
  if(background){restoreThreadView(visible);renderOpenTabs();return}
  renderAgentPanel();renderOpenTabs();
}
async function sendAgent(text){
  if(!D.enabled){toast('真实 Agent 需要从桌面应用启动。');return}
  if(!text||D.running)return;
  if(D.activeThreadId&&D.activeThreadId!==D.current?.threadId)throw new Error('另一对话正在运行，请等待完成或切回停止。');
  const requestedConsent=Boolean(D.current?.dataAuthorized||$('#agent-data-consent')?.checked),freshContext=pageContext({includeAccountData:requestedConsent}),capturedContext=state.composerContext;
  const context=capturedContext?{...freshContext,...capturedContext,route:capturedContext.route||freshContext.route,pageTitle:capturedContext.pageTitle||freshContext.pageTitle}:freshContext;
  if(requestedConsent&&capturedContext?.route==='holdings'&&state.nav==='holdings')context.holdingsSnapshot=freshContext.holdingsSnapshot;
  if(freshContext.route==='market'&&capturedContext?.route==='market'&&(state.nav==='market'||state.nav==='pages')){
    context.marketLayout=freshContext.marketLayout;
    context.market=freshContext.market;
    context.pageTitle=freshContext.pageTitle;
  }
  if(!D.current)await newSession({authorizeAccountData:requestedConsent});
  state.agentOpen=true;
  const localId='local-'+Date.now();
  D.turnMessageStart=D.messages.length;D.tools.clear();D.messages.push({id:localId,role:'user',text});D.running=true;D.activeThreadId=D.current.threadId;D.turnStartedAt=Date.now();render();
  try{
    const authorizeAccountData=Boolean(D.current?.dataAuthorized||requestedConsent),sent=await desktopCall(window.fundDesktop.sendMessage({threadId:D.current.threadId,text,pageContext:context,authorizeAccountData}));
    if(sent?.session){if(sent.session.threadId!==D.current?.threadId)forgetOpenSession(D.current?.threadId);D.current=sent.session;rememberOpenSession(sent.session.threadId);D.sessions=await desktopCall(window.fundDesktop.listSessions());renderSessions();renderOpenTabs();renderAgentPanel()}
    state.composerContext=null;renderAgentPanel();if($('#agent-input'))$('#agent-input').value='';
  }catch(error){
    D.running=false;D.activeThreadId=null;D.turnStartedAt=null;D.messages=D.messages.filter(row=>row.id!==localId);render();throw error;
  }
}
