function accountLoginMarkup(force,confirm=false){const title=force?'切换同花顺账户':'连接同花顺账户',desc=force?'扫码成功后，本机当前授权会替换为新账户。策略、回测和本地计划不会被删除。':'使用同花顺 App 扫描官方授权页二维码，并在手机上确认授权。';return `<div class="panda-dialog-head"><div><h2>${title}</h2><p>${desc}</p></div><button data-action="close-dialog">×</button></div><div class="panda-login-body"><div class="panda-login-visual"><div class="panda-phone-mark"><i></i><b>⌁</b></div><span>${confirm?'准备重新授权':'二维码显示在已打开的官方授权页'}</span></div><div class="panda-login-copy"><ol><li>打开手机同花顺 App</li><li>扫描浏览器官方授权页中的二维码</li><li>在手机上确认后等待本页自动更新</li></ol><div id="panda-login-status" class="panda-login-status ${confirm?'warning':'running'}"><i></i><span>${confirm?'确认后将强制发起新账号扫码授权。':esc(state.accountLoginMessage||'正在打开官方授权页…')}</span></div><p>工作台不会读取二维码内容、登录凭据、完整账户号或银行卡号。</p></div></div><div class="panda-login-footer">${confirm?`${button('取消','close-dialog','','quiet')}${button('开始扫码切换','confirm-switch-account','','primary')}`:button('关闭窗口','close-dialog','','quiet')}</div>`}
function showAccountLoginDialog(force,confirm=false){const dialog=$('#panda-dialog'),host=$('#panda-dialog-content');host.innerHTML=accountLoginMarkup(force,confirm);if(!dialog.open)dialog.showModal()}
function updateAccountLoginDialog(message,status='running'){const node=$('#panda-login-status');if(!node)return;node.className=`panda-login-status ${status}`;node.innerHTML=`<i></i><span>${esc(message)}</span>`}
async function loginFund(force=false){state.accountBusy=true;state.accountLoginMode=force?'switch':'login';state.accountLoginMessage='正在打开官方授权页…';state.accountLoginOpenedUrl='';render();showAccountLoginDialog(force);try{const started=await api('/api/fund/login',{force});state.accountLoginMessage=started.message;updateAccountLoginDialog(started.message);pollLogin()}catch(e){state.accountBusy=false;state.accountLoginMessage=e.message;updateAccountLoginDialog(e.message,'failed');toast(e.message);render()}}
async function pollLogin(){try{const r=await api('/api/fund/login-status');state.accountLoginMessage=r.message;if(r.authUrl&&r.authUrl!==state.accountLoginOpenedUrl){state.accountLoginOpenedUrl=r.authUrl;try{if(D.enabled)await desktopCall(window.fundDesktop.openFundLoginUrl(r.authUrl));else window.open(r.authUrl,'_blank','noopener');state.accountLoginMessage='官方扫码授权页已在系统浏览器打开，请使用同花顺 App 扫码并确认。'}catch(e){state.accountLoginMessage=`扫码页自动打开失败：${e.message}`}}if(r.running){updateAccountLoginDialog(state.accountLoginMessage);setTimeout(pollLogin,2200);return}state.accountBusy=false;updateAccountLoginDialog(state.accountLoginMessage||r.message,r.success?'success':'failed');toast(state.accountLoginMessage||r.message);if(r.success){state.holdings=null;state.holdingsError='';state.analysis=null;render();loadHoldings()}else render()}catch(e){state.accountBusy=false;state.accountLoginMessage=e.message;updateAccountLoginDialog(e.message,'failed');toast(e.message);render()}}

function shareResultForPlan(plan){const run=state.runs.find(x=>x.id===plan.backtestRunId);return run?.result||null}
function shareParamsPayload(result,item){const params={};for(const spec of item.params||[]){const value=result.parameters?.[spec.key]??item.defaultParams?.[spec.key]??spec.default;if(value!==undefined)params[spec.key]=value}return params}
function strategyShareCaption(channel,card){const where={wechat:'微信聊天',moments:'朋友圈',xiaohongshu:'小红书',tonghuashun:'同花顺'}[channel]||'策略分享';const result=card.result,m=result.metrics||{};return `${where}｜${card.strategyName}\n${card.fundName}${card.result.fundCode?`（${card.result.fundCode}）`:''}\n超额收益 ${pct(m.excessReturnPct)} · 绝对收益 ${pct(m.absoluteReturnPct??m.returnPct)} · 年化波动 ${n(m.volatilityPct)===null?'—':num(m.volatilityPct)+'%'}\n回测区间 ${result.period?.start||'—'} 至 ${result.period?.end||result.dataAsOf||'—'}\n历史回测不代表未来收益。`}
function roundedRect(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function fitText(ctx,text,maxWidth,size,family='sans-serif',weight=600){let px=size;ctx.font=`${weight} ${px}px ${family}`;while(ctx.measureText(text).width>maxWidth&&px>24){px-=2;ctx.font=`${weight} ${px}px ${family}`}return px}
