function showShareMarkup(){return `<div class="panda-share-head"><div><small>策略分享</small><h2>分享这套策略</h2><p>图片展示历史回测；二维码保存策略配置和标的，不含账户信息。</p></div><button type="button" data-action="close-share" aria-label="关闭">×</button></div><div class="panda-share-preview-wrap"><button type="button" class="panda-share-preview-trigger" data-action="open-share-viewer" aria-label="查看大图"><img id="panda-share-preview" alt="策略分享图片预览"></button><div id="panda-share-loading">正在生成图片…</div></div><div class="panda-share-actions">${button('保存图片','save-share-image','','primary')}</div><div class="panda-share-platforms"><span>分享到</span>${button('微信聊天','platform-share','data-channel="wechat"','quiet')}${button('朋友圈','platform-share','data-channel="moments"','quiet')}</div><p class="panda-share-tip">发送前请在系统分享面板确认。</p>`}
async function openStrategyShare(item,result,planName=''){const dialog=$('#panda-share-dialog'),host=$('#panda-share-content');host.innerHTML=showShareMarkup();state.shareCard=null;if(!dialog.open)dialog.showModal();try{const card=await buildShareCard(item,result,planName),image=$('#panda-share-preview'),loading=$('#panda-share-loading');image.onload=()=>loading?.remove();image.onerror=()=>{if(loading)loading.textContent='分享图片预览载入失败，请重新打开分享。'};image.src=card.dataUrl;if(image.complete&&image.naturalWidth>0)loading?.remove()}catch(e){const loading=$('#panda-share-loading');if(loading)loading.textContent=`图片生成失败：${e.message}`;toast(e.message)}}
async function openPlanShare(id){const plan=state.plans.find(x=>x.id===id);if(!plan)throw new Error('未找到这份策略计划。');const item=findStrategy(plan.strategyId),result=shareResultForPlan(plan);if(!item)throw new Error('当前版本的策略定义不可用。');await openStrategyShare(item,result,plan.name)}
async function downloadShareCard(){const card=state.shareCard;if(!card)throw new Error('分享图片还未生成。');const filename=`${card.strategyName.replace(/[\\/:*?"<>|]/g,'-')}-策略分享.png`,saved=await desktopCall(window.fundDesktop.saveStrategyShareImage({dataUrl:card.dataUrl,filename}));if(saved.canceled)return null;card.savedPath=saved.filePath;toast('分享图片已保存。');return saved.filePath}
async function shareToChannel(channel){const card=state.shareCard;if(!card)throw new Error('分享图片还未生成。');const target={wechat:'微信聊天',moments:'朋友圈'}[channel];if(!target)throw new Error('暂不支持这个分享渠道。');const filename=(card.strategyName||'策略').replace(/[^\w\u3400-\u9fff-]/g,'-')+'-策略分享.png';await desktopCall(window.fundDesktop.shareStrategyShare({dataUrl:card.dataUrl,filename,caption:strategyShareCaption(channel,card),channel}));toast('已打开系统分享面板，请选择微信及'+target+'后确认发送。')}
function showStrategyImport(payload){if(!payload||state.shareImport&&JSON.stringify(state.shareImport)===JSON.stringify(payload))return;state.shareImport=payload;const item=findStrategy(payload.strategyId),dialog=$('#panda-share-dialog'),host=$('#panda-share-content');if(!item){host.innerHTML=`<div class="panda-share-head"><div><small>STRATEGY IMPORT</small><h2>无法识别此策略</h2><p>此工作台没有对应策略定义，或版本已不可用。</p></div><button data-action="close-share">×</button></div>`}else if(String(item.version)!==String(payload.strategyVersion)){host.innerHTML=`<div class="panda-share-head"><div><small>STRATEGY IMPORT</small><h2>策略版本已更新</h2><p>分享版本 v${esc(payload.strategyVersion)}，本机版本 v${esc(item.version)}。为避免参数含义变化，本次不自动导入。</p></div><button data-action="close-share">×</button></div>`}else{const values=(item.params||[]).map(spec=>`<span>${esc(spec.label||spec.key)} <b>${esc(payload.params?.[spec.key]??item.defaultParams?.[spec.key]??'—')}${esc(spec.unit||'')}</b></span>`).join('');host.innerHTML=`<div class="panda-share-head"><div><small>STRATEGY IMPORT</small><h2>生成同款策略</h2><p>${esc(payload.strategyName||item.name)} · ${esc(payload.fundCode||'策略默认标的')}</p></div><button data-action="close-share">×</button></div><div class="panda-import-params">${values||'<span>策略未定义可复制参数</span>'}</div><p class="panda-share-tip">只导入规则、参数与基金代码；历史回测结果不会复制，生成后需要在本机重新回测。</p><div class="panda-share-actions">${button('生成同款策略','import-strategy-share',`data-strategy="${esc(payload.strategyId)}"`,'primary')}${button('取消','close-share','','quiet')}</div>`}if(!dialog.open)dialog.showModal();if(D.enabled)desktopCall(window.fundDesktop.clearPendingStrategyShare()).catch(()=>{})}
async function importSharedStrategy(){const payload=state.shareImport,item=findStrategy(payload?.strategyId);if(!item||String(item.version)!==String(payload.strategyVersion))throw new Error('策略版本不匹配，不能安全导入。');const params={};for(const spec of item.params||[]){params[spec.key]=payload.params?.[spec.key]??item.defaultParams?.[spec.key]??spec.default}const saved=await api('/api/strategy-variants',{strategyId:item.id,name:payload.strategyName||item.name,description:`从分享卡片导入 · 基于 Skill v${item.version}`,code:payload.fundCode||'',params});state.variants=await api('/api/strategy-variants');state.variant=saved;state.selected=item.id;state.nav='library';state.result=null;state.job=null;state.pendingCode=payload.fundCode||'';state.shareImport=null;$('#panda-share-dialog').close();render();toast('同款策略已生成，正在打开详情；请重新回测确认当前数据。')}
function watchForSharedStrategy(){if(!D.enabled)return;window.fundDesktop.onStrategyShare(payload=>showStrategyImport(payload));window.fundDesktop.getPendingStrategyShare().then(desktopCall).then(payload=>{if(payload)showStrategyImport(payload)}).catch(()=>{})}
