document.addEventListener('click',async e=>{const t=e.target.closest('[data-action],[data-nav],[data-session],[data-session-close],[data-session-rename],[data-session-pin],[data-session-project],[data-session-delete]');if(!t)return;try{if(t.dataset.nav){state.backtestRevision++;state.busy=false;state.job=null;state.paramEditing=false;state.paramDraft=null;state.composerContext=null;MS.returnTo=null;MS.fundTrail=[];MS.editing=false;MS.widgetPicker=false;MS.picker=false;MS.activeWorkId=null;MS.newPageMode=false;MS.saveFeedback='';MS.notice='';state.nav=t.dataset.nav;state.assistantFocus=null;state.assistantExampleIndex=0;if(state.nav==='market'){marketOpenLanding()}else if(state.nav==='pages'){MS.view='my-pages';MS.landingHome=false;MS.preview=null}else{MS.view='home';MS.fundCode=''}state.selected=null;state.result=null;state.runFocus=null;state.drill=null;state.agentPageFocus=null;render();if(state.nav==='plans')refreshPlanPerformance();if(state.nav==='history'){state.runs=await api('/api/strategy-runs');if(state.nav==='history')render()}return}if(t.dataset.session){await resumeSession(t.dataset.session);return}if(t.dataset.sessionClose){if(D.running||D.threadViews.get(t.dataset.sessionClose)?.running)throw new Error('该对话仍在运行，请完成后关闭标签。');const id=t.dataset.sessionClose,wasCurrent=D.current?.threadId===id;forgetOpenSession(id);if(wasCurrent){D.current=null;D.messages=[];D.tools.clear();const next=state.openSessionIds.at(-1);if(next){await resumeSession(next);return}state.agentOpen=false}render();return}if(t.dataset.sessionRename){await renameSession(t.dataset.sessionRename);return}if(t.dataset.sessionProject){await moveSessionToProject(t.dataset.sessionProject);return}if(t.dataset.sessionPin){const row=D.sessions.find(x=>x.threadId===t.dataset.sessionPin);D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:row.threadId,pinned:!row.pinned}));D.current=D.sessions.find(x=>x.threadId===D.current?.threadId)||D.current;renderSessions();renderOpenTabs();return}if(t.dataset.sessionDelete){await deleteSession(t.dataset.sessionDelete);return}const a=t.dataset.action;if(a==='open-strategy')await openStrategy(t.dataset.id);else if(a==='share-result'){const item=findStrategy(state.selected);await openStrategyShare(item,state.result)}else if(a==='share-plan')await openPlanShare(t.dataset.id);else if(a==='save-share-image')await downloadShareCard();else if(a==='platform-share')await shareToChannel(t.dataset.channel);else if(a==='import-strategy-share')await importSharedStrategy();else if(a==='open-share-viewer'){const image=$('#panda-share-preview'),viewerImage=$('#panda-share-viewer-image'),viewer=$('#panda-share-viewer-dialog');if(image?.src){viewerImage.src=image.src;viewer.showModal()}}else if(a==='close-share-viewer')$('#panda-share-viewer-dialog').close();else if(a==='ask-agent-about-page'){state.agentPageFocus=state.drill?'fund':state.runFocus?'run':null;const context=pageContext();$('#panda-dialog').close();openWorkbench('请帮我解读这份结果。',context)}else if(a==='close-share'){state.shareImport=null;state.shareCard=null;$('#panda-share-dialog').close()}else if(a==='history-favorite')toggleHistoryMarker('favorites',String(t.dataset.id));else if(a==='history-pin')toggleHistoryMarker('pinned',String(t.dataset.id));else if(a==='history-restore'){state.historyView.hidden=state.historyView.hidden.filter(x=>x!==String(t.dataset.id));saveHistoryView();render()}else if(a==='history-remove'){if(confirm('删除这条回测记录？它会移入“已移除”，可恢复；关联计划和回测底稿会保留。'))toggleHistoryMarker('hidden',String(t.dataset.id))}else if(a==='open-run')await openRun(t.dataset.id);else if(a==='back-library'){state.selected=null;state.variant=null;state.result=null;state.nav='library';render()}else if(a==='find-strategy')openWorkbench('请帮我选择一种适合我的基金投资方法。');else if(a==='clear-agent-context'){state.composerContext=null;renderAgentPanel()}else if(a==='confirm-save-plan')await confirmSavePlan();else if(a==='edit-params'){state.paramDraft=null;state.paramEditing=true;render()}else if(a==='cancel-param-edit'){state.paramEditing=false;state.paramDraft=null;render()}else if(a==='toggle-params'){state.paramsExpanded=!state.paramsExpanded;render()}else if(a==='load-variant'){state.skipDraftCapture=true;state.paramEditing=false;state.paramDraft=null;state.variant=state.variants.find(x=>x.id===t.dataset.id);state.result=null;state.job=null;state.paramEditing=true;state.paramsExpanded=true;render()}else if(a==='save-plan')await savePlan();else if(a==='plan-action')await planAction(t.dataset.id,t.dataset.planAction);else if(a==='refresh-holdings'){state.holdings=null;state.analysis=null;render();loadHoldings()}else if(a==='drill-fund')await drillFund(t.dataset.code);else if(a==='close-dialog'){state.planToSave=null;state.runFocus=null;state.drill=null;state.agentPageFocus=null;$('#panda-dialog').close()}else if(a==='remove-watch'){const b=await api('/api/watchlist',{code:t.dataset.code,remove:true});state.watchlist=b.watchlist||[];render()}else if(a==='pick-for-strategy'){state.pendingCode=t.dataset.code;state.nav='library';state.selected=null;$('#panda-dialog')?.close();render();toast(`已选择基金 ${t.dataset.code}，打开策略即可回测。`)}else if(a==='login-fund')await loginFund(false);else if(a==='switch-account')showAccountLoginDialog(true,true);else if(a==='confirm-switch-account')await loginFund(true)}catch(err){toast(err.message)}});
document.addEventListener('click',e=>{if(e.target.closest('[data-nav]'))state.strategyCompareOpen=false;const prompt=e.target.closest('[data-agent-prompt]');if(prompt){e.preventDefault();const input=$('#quick-agent-input');if(input){input.value=prompt.dataset.agentPrompt;$('#quick-agent-form').requestSubmit()}return}const target=e.target.closest('[data-action="toggle-strategy-favorite"],[data-action="toggle-strategy-compare"],[data-action="clear-strategy-compare"],[data-action="open-strategy-compare"],[data-action="back-strategy-compare"]');if(!target)return;e.preventDefault();e.stopImmediatePropagation();const action=target.dataset.action;if(action==='toggle-strategy-favorite'){const id=target.dataset.id;state.strategyFavorites=state.strategyFavorites.includes(id)?state.strategyFavorites.filter(value=>value!==id):[...state.strategyFavorites,id];saveStringList('panda.strategy.favorites.v1',state.strategyFavorites)}else if(action==='toggle-strategy-compare'){const id=target.dataset.id;if(state.strategyCompare.includes(id))state.strategyCompare=state.strategyCompare.filter(value=>value!==id);else if(state.strategyCompare.length<3)state.strategyCompare.push(id);else{toast('最多对比 3 个策略');return}if(state.strategyCompareOpen&&state.strategyCompare.length<2)state.strategyCompareOpen=false}else if(action==='clear-strategy-compare'){state.strategyCompare=[];state.strategyCompareOpen=false}else if(action==='open-strategy-compare'){if(state.strategyCompare.length<2){toast('至少选择 2 个策略后再对比');return}state.strategyCompareOpen=true}else state.strategyCompareOpen=false;render()},true);
