async function deleteSession(threadId){const row=D.sessions.find(x=>x.threadId===threadId);if(!row)return;if(D.activeThreadId===threadId||D.current?.threadId===threadId&&D.running){toast('请先停止或等待这个对话完成。');return}if(!confirm(`删除对话“${row.title}”？删除后将从历史会话中移除。`))return;const wasCurrent=D.current?.threadId===threadId,outcome=await desktopCall(window.fundDesktop.deleteSession(threadId));D.sessions=Array.isArray(outcome)?outcome:(outcome?.sessions||[]);forgetOpenSession(threadId);D.threadViews.delete(threadId);if(wasCurrent){D.current=null;D.messages=[];D.tools.clear();D.pendingInput=null;D.turnStartedAt=null}render();if(wasCurrent&&D.sessions.length){try{await resumeSession(D.sessions[0].threadId)}catch(e){toast(`会话已删除；下一条会话加载失败：${e.message}`);return}}toast(outcome?.warning?'对话已从本机历史移除；模型服务归档暂未完成。':'对话已删除')}
