async function loadMarketIndices(force=false){
  if(state.marketIndicesLoading)return;
  state.marketIndicesLoading=true;state.marketIndicesError='';
  try{state.marketIndices=await api('/api/market/indices'+(force?'?force=1':''));if(typeof marketAlertCheck==='function')marketAlertCheck()}
  catch(error){state.marketIndicesError=error.message||'指数行情暂不可用'}
  finally{state.marketIndicesLoading=false;render()}
}
async function bootstrap(){ensureChrome();setInterval(()=>{if(D.running&&$('#agent-elapsed'))$('#agent-elapsed').textContent=Math.max(0,Math.floor((Date.now()-(D.turnStartedAt||Date.now()))/1000))+' 秒'},1000);try{await refreshLocal();render();startMonitor();loadHoldings();loadShowcases();loadMarketIndices();if(D.enabled){watchForSharedStrategy();await initDesktop()}else render()}catch(e){$('#panda-content').innerHTML=`<div class="panda-empty-page"><div><div class="empty-symbol">!</div><h2>本地服务尚未启动</h2><p>${esc(e.message)}</p></div></div>`}}
bootstrap();
